(()=>{'use strict';

const URLS={pyramid:'data/behind-the-curtain-pyramid.json',core:'data/behind-the-curtain.json',families:'data/behind-the-curtain-family-access.json',living:'data/behind-the-curtain-living-access.json',history:'data/behind-the-curtain-living-access-history.json',continuity:'data/behind-the-curtain-continuity-layers.json'};
const MODE_RANK={proof:0,structural:1,symbolic:2};
const state={mode:'structural',selectedLevel:'human-apex',models:null,lastLoaded:null,timer:null};
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const slug=value=>String(value||'').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');
const label=value=>String(value||'').replace(/_/g,' ').replace(/\b\w/g,char=>char.toUpperCase());
const clamp=value=>Math.max(0,Math.min(100,Number(value)||0));const array=value=>Array.isArray(value)?value:[];
const list=value=>array(value).length?`<ul>${value.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'<p class="muted">No current record.</p>';
const classification=value=>`<span class="classification ${esc(value||'unsupported')}">${esc(label(value||'unsupported'))}</span>`;
const refKey=ref=>`${ref.dataset}:${ref.id}`;

async function load(url){const response=await fetch(`${url}?v=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error(`${url}: HTTP ${response.status}`);return response.json()}
function buildIndexes(models){const historical=array(models.families.historicalArchitects).map(item=>({...item,id:slug(item.name)}));return{living:new Map(array(models.living.candidates).map(item=>[item.id,{...item,_dataset:'living'}])),family:new Map(array(models.families.families).map(item=>[item.id,{...item,_dataset:'family'}])),core:new Map(array(models.core.powerCenters).map(item=>[item.id,{...item,_dataset:'core'}])),historical:new Map(historical.map(item=>[item.id,{...item,_dataset:'historical'}])),symbolic:new Map(array(models.pyramid.symbolicDossiers).map(item=>[item.id,{...item,_dataset:'symbolic'}]))}}
function resolve(ref){if(!ref||!ref.dataset||!ref.id)return null;return state.models?.indexes?.[ref.dataset]?.get(ref.id)||null}
function displayName(entity){return entity?.name||entity?.title||'Unresolved entity'}
function subtitle(entity){if(!entity)return'';if(entity._dataset==='living')return entity.currentRole;if(entity._dataset==='family')return `${entity.type} · ${array(entity.jurisdictions).join(' · ')}`;if(entity._dataset==='core')return `${label(entity.entityType)} · ${array(entity.jurisdictions).join(' · ')}`;if(entity._dataset==='historical')return'Historical architect under continuity review';if(entity._dataset==='symbolic')return'Symbolic and interpretive dossier';return''}
function score(entity){if(entity?.accessScore!=null)return Number(entity.accessScore);if(entity?.structuralPowerScore!=null)return Number(entity.structuralPowerScore);return null}
function entityClassification(entity){return entity?.classification||'unsupported'}
function sourceIndex(){const combined=[...array(state.models.core.sources).map(x=>({...x,_model:'core'})),...array(state.models.families.sources).map(x=>({...x,_model:'families'})),...array(state.models.living.sources).map(x=>({...x,_model:'living'}))];return new Map(combined.map(item=>[item.id,item]))}
function sourcesFor(entity){const index=sourceIndex();return array(entity?.sourceIds).map(id=>index.get(id)).filter(Boolean)}
function sourceBlock(entity){const sources=sourcesFor(entity);if(!sources.length)return'<p class="muted">No directly resolved source record in this package.</p>';return sources.map(source=>`<article class="source-card"><strong>${esc(source.publisher)}</strong><h4>${esc(source.title)}</h4><p><b>Establishes:</b> ${esc(source.establishes)}</p><p><b>Does not establish:</b> ${esc(source.doesNotEstablish)}</p><a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">Open source record</a></article>`).join('')}
function memberButtons(refs){return array(refs).map(ref=>{const entity=resolve(ref);if(!entity)return`<span class="entity-chip muted">Identity unresolved: ${esc(ref.id)}</span>`;const symbolic=entity._dataset==='symbolic'?' symbolic':'';return`<button class="entity-chip${symbolic}" type="button" data-entity="${esc(refKey(ref))}">${esc(displayName(entity))}</button>`}).join('')}
function modeAllows(level){return MODE_RANK[state.mode]>=MODE_RANK[level.minimumMode||'proof']}

function renderPyramid(){const target=$('#pyramid-levels');if(!target)return;const levels=[...array(state.models.pyramid.levels)].sort((a,b)=>b.level-a.level);target.innerHTML=levels.map(level=>{const width=28+(12-level.level)*6.18;const classes=['pyramid-level',level.id===state.selectedLevel?'active':'',level.minimumMode==='symbolic'?'symbolic':'',level.classification==='disputed'?'disputed':'',modeAllows(level)?'':'hidden-mode'].filter(Boolean).join(' ');const count=array(level.memberRefs).filter(ref=>resolve(ref)).length;return`<button class="${classes}" type="button" data-level="${esc(level.id)}" style="--tier-width:${width}%"><span class="pyramid-line"><span class="pyramid-number">${esc(level.level)}</span><span class="pyramid-copy"><strong>${esc(level.name)}</strong><small>${esc(level.kicker)}</small></span><span class="pyramid-count">${count} named</span></span></button>`}).join('');const selected=levels.find(level=>level.id===state.selectedLevel&&modeAllows(level))||levels.find(modeAllows);if(selected){state.selectedLevel=selected.id;renderLevelDetail(selected)}}
function renderLevelDetail(level){const target=$('#pyr-detail');if(!target)return;target.innerHTML=`<span class="level-mark">LEVEL ${esc(level.level)} · ${esc(level.kicker)}</span><h3>${esc(level.name)}</h3>${classification(level.classification)}<p><strong>${esc(level.question)}</strong></p><p>${esc(level.thesis)}</p><div class="pyr-detail-members">${memberButtons(level.memberRefs)}</div><details open><summary>Mechanisms of access</summary>${list(level.mechanisms)}</details><div class="pyr-boundary"><strong>COUNTERWEIGHT</strong><p>${esc(level.counterweight)}</p></div>`}
function renderHumanApex(){const target=$('#human-apex-grid');if(!target)return;const people=array(state.models.living.candidates).filter(item=>item.rank&&item.rank<=10).sort((a,b)=>a.rank-b.rank);if(people.length!==10){target.innerHTML='<article class="pyr-fail"><h3>Human apex unavailable</h3><p>The page fails closed unless ten current source-verified candidates pass the evidence contract.</p></article>';return}target.innerHTML=people.map(person=>`<article class="apex-person"><span class="apex-rank">#${esc(person.rank)}</span><div><h3><button class="entity-chip" type="button" data-entity="living:${esc(person.id)}">${esc(person.name)}</button></h3><p>${esc(person.currentRole)}</p><div class="mini-bars">${Object.entries(person.dimensions||{}).map(([key,value])=>`<span class="mini-bar">${esc(label(key))}<i style="--v:${clamp(value)}%"></i></span>`).join('')}</div></div><span class="apex-score">${Number(person.accessScore).toFixed(1)}</span></article>`).join('')}
function renderChokepoints(){const target=$('#choke-grid');if(!target)return;target.innerHTML=array(state.models.pyramid.chokePoints).map((point,index)=>`<article class="choke-card"><span class="choke-num">${String(index+1).padStart(2,'0')}</span><h3>${esc(point.name)}</h3><p><strong>${esc(point.question)}</strong></p><div class="pyr-detail-members">${memberButtons(point.memberRefs)}</div></article>`).join('')}
function stepHtml(step){if(step.label)return`<span class="path-node">${esc(step.label)}</span>`;const entity=resolve(step);if(!entity)return`<span class="path-node muted">Unresolved: ${esc(step.id)}</span>`;return`<button class="path-node entity-chip" type="button" data-entity="${esc(refKey(step))}">${esc(displayName(entity))}</button>`}
function renderPathways(){const target=$('#pathway-grid');if(!target)return;const pathways=array(state.models.pyramid.pathways).filter(item=>state.mode==='symbolic'||item.classification!=='symbolic_or_mythological');target.innerHTML=pathways.map(path=>`<article class="pyr-card"><span class="eyeline">${esc(label(path.classification))}</span><h3>${esc(path.title)}</h3><div class="pathway">${array(path.steps).map((step,index)=>`<span class="path-step">${index?'<span class="path-arrow">→</span>':''}${stepHtml(step)}</span>`).join('')}</div><div class="pyr-boundary"><strong>BOUNDARY</strong><p>${esc(path.boundary)}</p></div></article>`).join('')}
function renderDynasties(){const target=$('#dynasty-grid');if(!target)return;const families=[...array(state.models.families.families)].sort((a,b)=>a.rank-b.rank);target.innerHTML=families.map(family=>`<article class="pyr-card"><span class="eyeline">#${esc(family.rank)} · ${esc(family.type)}</span><h3><button class="entity-chip" type="button" data-entity="family:${esc(family.id)}">${esc(family.name)}</button></h3><p><strong>Access score:</strong> ${esc(family.accessScore)}/100 · ${esc(label(family.confidence))} confidence</p><p><strong>Structures reached:</strong> ${esc(array(family.structuresReached).join(' · '))}</p><p>${esc(array(family.documentedAccess)[0]||'Evidence summary unavailable.')}</p><div class="pyr-boundary"><strong>NOT ESTABLISHED</strong><p>${esc(family.unsupportedClaim)}</p></div></article>`).join('')}
function renderCouncils(){const target=$('#council-grid');if(!target)return;const review=state.models.pyramid.innerCouncilsReview;const refs=state.models.pyramid.levels.find(level=>level.id==='inner-councils')?.memberRefs||[];const bodyCards=array(review.namedBodies).map(name=>`<article class="pyr-card"><span class="eyeline">Named decision body</span><h3>${esc(name)}</h3><p>Inspect its legal mandate, membership, decision rights, source record and implementation limits before inferring broader coordination.</p></article>`).join('');const centerCards=refs.map(ref=>{const entity=resolve(ref);return entity?`<article class="pyr-card"><span class="eyeline">Structural system</span><h3><button class="entity-chip" data-entity="${esc(refKey(ref))}" type="button">${esc(entity.name)}</button></h3><p>${esc(array(entity.mechanisms).join(' · '))}</p><p><strong>Counterargument:</strong> ${esc(entity.strongestCounterargument)}</p></article>`:''}).join('');target.innerHTML=`<article class="pyr-card"><span class="eyeline">${esc(label(review.status))}</span><h3>Current finding</h3><p>${esc(review.currentFinding)}</p></article>${centerCards}${bodyCards}`}
function renderSymbolic(){const target=$('#symbolic-grid');if(!target)return;const visible=state.mode==='symbolic';target.closest('.pyr-section').style.display=visible?'':'none';if(!visible){target.innerHTML='';return}target.innerHTML=array(state.models.pyramid.symbolicDossiers).map(item=>`<article class="symbolic-card">${classification(item.classification)}<h3><button class="entity-chip symbolic" data-entity="symbolic:${esc(item.id)}" type="button">${esc(item.name)}</button></h3><p>${esc(item.summary)}</p><p><strong>Interpretive lenses:</strong> ${esc(array(item.interpretations).join(' · '))}</p><p class="not-established"><strong>Not established:</strong> ${esc(item.notEstablished)}</p></article>`).join('')}
function renderFreshness(){const target=$('#freshness-grid');if(!target)return;const asOfDates=[state.models.pyramid.asOf,state.models.core.asOf,state.models.families.asOf,state.models.living.asOf].filter(Boolean).sort();const latest=asOfDates[asOfDates.length-1]||'Unknown';const nextReviews=array(state.models.living.candidates).map(item=>item.nextReviewDue).filter(Boolean).sort();const next=nextReviews[0]||'Not scheduled';const snapshots=array(state.models.history.snapshots).length;const poll=state.models.pyramid.updatePolicy?.pollMinutes||15;const oldest=asOfDates[0]||latest;const staleDays=Math.max(0,Math.floor((Date.now()-Date.parse(`${oldest}T00:00:00Z`))/86400000));const stale=staleDays>(state.models.pyramid.updatePolicy?.reviewCadenceDays||31);target.innerHTML=`<article class="fresh-card"><span class="fresh-dot${stale?' stale':''}"></span><strong>${esc(latest)}</strong><span>latest model date</span></article><article class="fresh-card"><strong>${esc(next)}</strong><span>next scheduled role review</span></article><article class="fresh-card"><strong>${esc(snapshots)}</strong><span>preserved ranking snapshots</span></article><article class="fresh-card"><strong>${esc(poll)} min</strong><span>browser evidence refresh interval</span></article>`}
function renderSources(){const target=$('#source-grid');if(!target)return;const all=[...sourceIndex().values()];const unique=[...new Map(all.map(item=>[item.url,item])).values()];target.innerHTML=unique.map(source=>`<article class="source-card"><span class="eyeline">${esc(source.publisher)}</span><h3>${esc(source.title)}</h3><p><strong>Establishes:</strong> ${esc(source.establishes)}</p><p><strong>Does not establish:</strong> ${esc(source.doesNotEstablish)}</p><a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">Open source record</a><small>${esc(source.date||'Reviewed source')}</small></article>`).join('')}
function renderStats(){const refs=new Set();array(state.models.pyramid.levels).forEach(level=>array(level.memberRefs).forEach(ref=>refs.add(refKey(ref))));array(state.models.pyramid.chokePoints).forEach(point=>array(point.memberRefs).forEach(ref=>refs.add(refKey(ref))));const sourceCount=[...sourceIndex().values()].length;const dates=[state.models.pyramid.asOf,state.models.core.asOf,state.models.families.asOf,state.models.living.asOf].filter(Boolean).sort();$('#pyr-level-count').textContent=state.models.pyramid.levels.length;$('#pyr-name-count').textContent=refs.size;$('#pyr-source-count').textContent=sourceCount;$('#pyr-evidence-date').textContent=dates[dates.length-1]||'Unknown';$('#pyr-boundary').textContent=`${state.models.pyramid.editorialBoundary} ${state.models.living.editorialBoundary} ${state.models.families.editorialBoundary}`}
function profileBlocks(entity){if(entity._dataset==='living')return`<div class="profile-block"><h4>Verified role</h4><p>${esc(entity.currentRole)}</p><p class="muted">Verified ${esc(entity.verifiedAt)} · review due ${esc(entity.nextReviewDue)}</p></div><div class="profile-block"><h4>Structures reached</h4>${list(entity.structuresReached)}</div><div class="profile-block"><h4>Mechanisms of access</h4>${list(entity.mechanisms)}</div><div class="profile-block"><h4>Constraints</h4>${list(entity.constraints)}</div><div class="profile-block"><h4>Removal triggers</h4>${list(entity.removalTriggers)}</div><div class="profile-block"><h4>Strongest counterargument</h4><p>${esc(entity.strongestCounterargument)}</p></div>`;if(entity._dataset==='family')return`<div class="profile-block"><h4>Documented access</h4>${list(entity.documentedAccess)}</div><div class="profile-block"><h4>Structures reached</h4>${list(entity.structuresReached)}</div><div class="profile-block"><h4>Constraints</h4>${list(entity.constraints)}</div><div class="profile-block"><h4>Strongest counterargument</h4><p>${esc(entity.strongestCounterargument)}</p></div><div class="profile-block"><h4>Claim not supported</h4><p>${esc(entity.unsupportedClaim)}</p></div>`;if(entity._dataset==='core')return`<div class="profile-block"><h4>Mechanisms</h4>${list(entity.mechanisms)}</div><div class="profile-block"><h4>Chokepoints</h4>${list(entity.chokepoints)}</div><div class="profile-block"><h4>What it can stop</h4>${list(entity.canStop)}</div><div class="profile-block"><h4>Dependencies</h4>${list(entity.dependencies)}</div><div class="profile-block"><h4>Constraints</h4>${list(entity.constraints)}</div><div class="profile-block"><h4>Replacement test</h4><p>${esc(entity.replacementTest)}</p></div><div class="profile-block"><h4>Strongest counterargument</h4><p>${esc(entity.strongestCounterargument)}</p></div>`;if(entity._dataset==='historical')return`<div class="profile-block"><h4>Documented history</h4><p>${esc(entity.documentedHistory)}</p></div><div class="profile-block"><h4>Present assessment</h4><p>${esc(entity.presentAssessment)}</p></div>`;if(entity._dataset==='symbolic')return`<div class="profile-block"><h4>Interpretive summary</h4><p>${esc(entity.summary)}</p></div><div class="profile-block"><h4>Interpretations</h4>${list(entity.interpretations)}</div><div class="profile-block"><h4>Not established</h4><p>${esc(entity.notEstablished)}</p></div>`;return'<p>No profile detail available.</p>'}
function openProfile(key){const [dataset,...rest]=String(key).split(':');const id=rest.join(':');const entity=state.models.indexes?.[dataset]?.get(id);if(!entity)return;const modal=$('#pyr-modal'),content=$('#pyr-modal-content');const entityScore=score(entity);content.innerHTML=`<div class="eyebrow">${esc(label(dataset))} profile</div><h2 id="pyr-modal-title">${esc(displayName(entity))}</h2><p class="lead">${esc(subtitle(entity))}</p>${classification(entityClassification(entity))}${entityScore!=null?`<p class="profile-score">${entityScore.toFixed(1)}<small>/100</small></p>`:''}<div class="profile-grid">${profileBlocks(entity)}</div><section><h3>Source boundary</h3><div class="source-grid">${sourceBlock(entity)}</div></section>`;modal.classList.add('open');document.body.style.overflow='hidden';$('#pyr-modal-close').focus()}
function closeProfile(){$('#pyr-modal')?.classList.remove('open');document.body.style.overflow=''}
function renderAll(){renderStats();renderPyramid();renderHumanApex();renderChokepoints();renderPathways();renderDynasties();renderCouncils();renderSymbolic();renderFreshness();renderSources();$$('[data-view-mode]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.viewMode===state.mode)))}
function showToast(message){const toast=$('#pyr-toast');if(!toast)return;toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2600)}
async function refresh({silent=false}={}){const refreshState=$('#pyr-refresh-state');if(refreshState)refreshState.textContent='SYNC';try{const [pyramid,core,families,living,history,continuity]=await Promise.all(Object.values(URLS).map(load));const models={pyramid,core,families,living,history,continuity};models.indexes=buildIndexes(models);state.models=models;state.lastLoaded=new Date();renderAll();if(refreshState)refreshState.textContent='LIVE';if(!silent)showToast('Evidence model refreshed and re-rendered.');clearInterval(state.timer);const minutes=Math.max(5,Number(pyramid.updatePolicy?.pollMinutes)||15);state.timer=setInterval(()=>refresh({silent:true}),minutes*60*1000)}catch(error){console.error(error);if(refreshState)refreshState.textContent='CLOSED';const target=$('#pyramid-levels');if(target)target.innerHTML='<article class="pyr-fail"><h3>The Pyramid has failed closed.</h3><p>One or more evidence packages could not be loaded. No names or conclusions are invented when the source model is unavailable.</p></article>';const detail=$('#pyr-detail');if(detail)detail.innerHTML='<span class="level-mark">EVIDENCE PACKAGE ERROR</span><h3>Display suspended.</h3><p>Check the source packages and rebuild workflow.</p>';if(!silent)showToast('Evidence refresh failed closed.')}}
function bind(){document.addEventListener('click',event=>{const level=event.target.closest('[data-level]');if(level){state.selectedLevel=level.dataset.level;renderPyramid();return}const entity=event.target.closest('[data-entity]');if(entity){openProfile(entity.dataset.entity);return}const mode=event.target.closest('[data-view-mode]');if(mode){state.mode=mode.dataset.viewMode;renderAll();showToast(`${mode.textContent.trim()} activated.`)}});$('#pyr-refresh')?.addEventListener('click',()=>refresh());$('#pyr-modal-close')?.addEventListener('click',closeProfile);$('#pyr-modal')?.addEventListener('click',event=>{if(event.target.id==='pyr-modal')closeProfile()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeProfile()});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.lastLoaded&&Date.now()-state.lastLoaded.getTime()>15*60*1000)refresh({silent:true})})}
function init(){bind();refresh()}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init):init();
})();
